typedef int SSEventId;
typedef unsigned int nslSoundId;
typedef unsigned int nslEmitterId;

#define NULL 0
#define MAX_TOTAL_EVENTS 100
#define NSL_INVALID_ID 0
#define NSL_SOUNDPARAM_VOLUME 0
#define assert(x) ((void)0)

enum EventType
{
	SS_MANY,
	SS_ONCE_PER_ENTITY,
	SS_ONCE,
	SS_LAST = 105
};

class vector3d
{
public:
	float x, y, z;
};

class entity
{
public:
	vector3d get_abs_position() const;
};

class nlVector3d
{
	float value[3];
public:
	float &operator[](int index) { return value[index]; }
};

class EventMapType
{
public:
	EventType type;
	int numSrcs;
	unsigned int srcs[30];
	nslSoundId playEvent(entity *e);
};

class CurrentSoundEvent
{
public:
	EventType event;
	nslSoundId snd;
	entity *myEntity;
	float fadeInTime;
	float fadeOutTime;
	bool fadingOut;
	char pad[3];
	nslEmitterId eId;
	void clear();
};

class singleton
{
	void *instance;
};

class os_developer_options
{
public:
	enum flags_t { FLAG_NO_AUDIO };
	static os_developer_options *inst();
	bool is_flagged(flags_t flag);
};

extern int EventFreq[];
nslEmitterId nslCreateEmitter(nlVector3d &position);
void nslSetSoundEmitter(nslEmitterId emitter, nslSoundId sound);
void nslSetSoundParam(nslSoundId sound, int param, float value);

class SoundScriptManager : public singleton
{
	EventMapType eventMap[SS_LAST];
	char scheduledLevelEvents[100 * 16];
	CurrentSoundEvent playingEvents[MAX_TOTAL_EVENTS];
	int numEvents;
	bool paused;
public:
	void endEvent(SSEventId e, float fadeOutTime = 0);
	SSEventId playEvent(EventType etype, entity *e, float fadeInTime);
};

SSEventId SoundScriptManager::playEvent(EventType etype, entity *e, float fadeInTime)
{
	if (paused) 
		return -1;

	if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
	{
		int eventIdx = -1, i = 0;

		// Stop the previously playing one
		for (i=0; i < MAX_TOTAL_EVENTS; i++)
		{
			if (eventIdx < 0 && playingEvents[i].event == SS_LAST)
			{
				eventIdx = i;
			}

			if (EventFreq[etype] != SS_MANY && playingEvents[i].event == etype)
			{
				if ((playingEvents[i].myEntity == e && EventFreq[etype] == SS_ONCE_PER_ENTITY) ||
				    (	EventFreq[etype] == SS_ONCE))
					endEvent(i);
			}
		}

		// Sucessfully found a free slot!
		if (eventIdx >= 0)
		{
			nlVector3d v;
			playingEvents[eventIdx].fadingOut = false;
			// If we found a slot, play!
			assert (fadeInTime >= 0);


			playingEvents[eventIdx].fadeInTime = fadeInTime;
			playingEvents[eventIdx].event = etype;
			playingEvents[eventIdx].snd = eventMap[etype].playEvent(e);
			playingEvents[eventIdx].myEntity = e;
			playingEvents[eventIdx].fadingOut = false;
			if (playingEvents[eventIdx].snd == NSL_INVALID_ID)
			{
				playingEvents[eventIdx].clear();
				return -1;
			}
			else if (playingEvents[eventIdx].fadeInTime > 0)
				nslSetSoundParam(playingEvents[eventIdx].snd, NSL_SOUNDPARAM_VOLUME, 0.0f);

			if (e != NULL)
			{
				v[0] = e->get_abs_position().x;
				v[1] = e->get_abs_position().y;
				v[2] = e->get_abs_position().z;
				playingEvents[eventIdx].eId = nslCreateEmitter(v);
				nslSetSoundEmitter(playingEvents[eventIdx].eId, playingEvents[eventIdx].snd);
			}


			// Return the id
			return eventIdx;
		}
		else 
			return -1;
	}
	else
		return -1;
}
